const P=text=>({type:'p',text}),H=(text,level=2)=>({type:'heading',text,level}),T=(headers,rows)=>({type:'table',headers,rows}),F=(file,caption)=>({type:'figure',file,caption}),L=items=>({type:'list',items});
const O=(title,purpose,access,steps,result,limits)=>({type:'procedure',title,purpose,access,steps,result,limits});
const source=text=>P('Source evidence: '+text);
const date='27 October 2026',version='1.1';
const common=[
 P('Naming: these documents use the requested SiteTrace title. The inspected application displays MCPA (Material & Construction Property Allocation), Construction Asset Management and Accountability System, and BuildRight Corp. Follow the on-screen MCPA labels when using the application. No application branding was changed.'),
 P('Verification scope: instructions describe the current repository implementation. Most interface screenshots were captured on 12 October using isolated local PGlite records. People & Accountability was refreshed on 27 October after feature removal, using the local functionality-audit fixture. Authentication is modeled locally. They are training illustrations, not production screenshots or proof of deployed services.'),
 P('The capture browser blocked external HTTPS. Original training captures permitted business reads only after fixture setup; the updated People capture came from a test run that writes only to disposable local fixtures. No live login, migration, stock change, approval, handover, receipt, return, role change, or notification-read update was performed. The live REQ-00001 test was not accessed. Its unchanged state was not independently compared because production was not contacted.'),
 P('Operational availability: use the procedures only in an authorized company workspace whose required Supabase database functions, policies and services are installed. The original training captures did not execute write procedures; current automated regression checks use disposable local records. Supabase deployment, email delivery, private file retrieval, optical QR scanning and the monitoring scheduler remain unverified in production.'),
 P('Screenshot conventions: all figure captions identify the local training environment. Fixture names, example.test addresses, asset references beginning DOC-, and transaction numbers in the 007xx range are synthetic. Password fields are empty or absent. No authentication tokens or receiving QR secrets are embedded in the manuals. Figures are numbered separately in each manual.'),
];
const loginProcedure=O('Sign in to your company workspace','Open the pages and actions authorized for your company identity.','An issued company account, an Active company profile.',[
 'Open the application address supplied by your administrator. Both index.html and 2-engr/index.html use authenticated role checks; the URL alone does not select your role.',
 'In Welcome back, enter your company Email and Password. Show reveals the password locally; Hide masks it again. Keep passwords out of shared screenshots.',
 'Select Sign In, or press Enter in a completed login form. Wait for your profile and authorized navigation to load.',
 'Check the account name and role in the top-right Account menu and sidebar. If they are wrong, stop and contact Admin.'
],'The application opens the role’s home module. Admin, Engineer, Architect and Tool Handler open Dashboard; Secretary opens Material Requests.','An Auth login without an authorized active profile is refused. Incorrect email or password., an inactive-account message, or a profile-verification failure requires correction or administrator assistance. There is no public account registration.');
const setupProcedure=O('Reset your password','Recover access to an existing company account.','A valid password-reset email, configured Supabase Auth redirects and working email delivery.',[
 'Enter your Email on the login page and select Forgot password?.',
 'For a reset request, read the neutral response: If an account exists for this email, a password reset link has been sent. This message does not confirm that the email exists or that delivery succeeded.',
 'Open the fresh email link and use Set your password. Enter a New password of at least 12 characters and select Save password.',
 'After the application signs you out, sign in with the new password. Cancel and sign out abandons the setup screen.'
],'The password is saved by Supabase Auth and the user signs in again.','An invalid or expired reset link needs a fresh password reset. This documentation session did not send or receive email.');
const accountProcedure=O('Review your account, change display mode, and log out','Confirm your identity, select a display preference and close your session.','Any authorized role; offline demo uses Exit demo.',[
 'Open the top-right Account menu and select My Account, or select Settings in the sidebar.',
 'Review the name, role and Active company account message. Account roles are managed by an administrator.',
 'Select Change light / night mode. The Account menu also offers Change theme. The preference is stored in the current browser.',
 'Select Log Out from My account or the Account menu. Wait for the sign-in screen and its sign-out confirmation.'
],'Display mode changes immediately. Log Out clears the local application workspace and asks Supabase to end the local session.','Sign out could not be confirmed. requires Retry sign out before leaving a shared device. Settings does not provide a profile editor, email editor, role switcher or in-session password-change form.');
const statuses=T(['Record / label','Meaning and next step'],[
 ['Request: Pending review','Awaiting Admin approval or rejection. The requester may Withdraw request while eligible.'],
 ['Request: Approved','Selected whole asset records are reserved; custody is unchanged. Admin can release. The requester may Cancel reservation before release.'],
 ['Request: Released','A linked transfer and handover code exist. This does not mean the receiver has accepted custody.'],
 ['Request: Inspected / completed','The linked receiver inspection has completed. Review its actual per-tool conditions and any damage/missing cases.'],
 ['Request: Rejected / Withdrawn / Canceled','The original record stays in history. Rejection includes a reason. There is no edit-and-resubmit action for the saved request; submit a new request if needed.'],
 ['Transfer: Awaiting receipt','Pending handover. Sender custody and the tool reservation remain until inspection/receipt or eligible cancellation.'],
 ['Transfer: Damage refused · awaiting sender','The entire handover is held. Custody and reservations remain. Eligible sender/requester follow-up is required.'],
 ['Transfer: Inspected / completed','The named receiver submitted all inspections. Review the recorded conditions; completion may include accepted damage or missing items.'],
 ['Return: Returned','A saved return record; the implementation has no separate Admin approval queue for returns.'],
 ['Repair: Reported / Under repair / Completed','Report created; Admin started work; Admin closed the case after completion. Under repair can be derived from the repair case rather than a different raw equipment value.'],
 ['Missing: Missing / Recovered','Unresolved loss report, or an Admin-recorded recovery. Damaged recovery opens a repair case.']
]);
const availability=P('Status and availability are separate. The current availability helper shows Deployed for equipment at a project with In Use status, Available when there is no project or the normalized state is In Office, and Unavailable otherwise. An Available status at a project can therefore display Unavailable. Request eligibility separately requires available stock with no holder, positive quantity and no approved reservation or pending/refused transfer. Do not use a dashboard count or availability caption alone as permission to issue equipment. Movement summary totals can also include Withdrawn/Canceled records in the open count; use each saved status badge to decide what remains actionable.');
const glossary=[
 ['Accountable profile','Permanent company person record linked to an Auth login. Custody and history remain attached to this identity.'],
 ['Active account','Authorized profile whose account_status is active and whose Auth linkage is valid.'],
 ['Asset record','One inventory record identified by an asset ID. It may represent one item or an entire bulk quantity.'],
 ['Availability','Location/state-derived caption; separate from movement eligibility and equipment condition.'],
 ['Custody / holder','The person recorded as accountable for the equipment. Pending dispatch does not change the holder.'],
 ['Destination project','Existing project selected for a request, transfer, return or resolution.'],
 ['Receiving QR','A short-lived receiver-and-project reference generated before dispatch; valid for 15 minutes and revocable. It never confirms receipt.'],
 ['Handover code / QR','The transfer reference shared after dispatch, for example TRF-00705. It opens the saved transfer for inspection.'],
 ['Equipment tag','An asset ID QR tag used to identify equipment. It does not grant custody or override named-recipient rules.'],
 ['Reservation','Allocation of the whole selected asset record to an approved request or pending/refused transfer.'],
 ['Inspection','Per-tool condition, notes when needed, testing confirmation for received non-missing items, and a custody decision for damaged items.'],
 ['REQ / TRF / RTN / REP / MIS','Equipment request, transfer, return, repair and missing-report reference prefixes. Numbering comes from a shared sequence; gaps are normal.'],
 ['CR / PUR','Consumable purchase request and record-only purchase ledger reference prefixes. These are different from equipment requests.'],
 ['RPC','Database function called by the application. It validates the authenticated role, current state and ownership.'],
 ['RLS','Row-level security: database rules restricting which records an authenticated account may read or change.'],
 ['Snapshot','An observation of inventory saved at an actual capture time. It does not reconstruct earlier inventory.'],
 ['Offline demonstration','Explicit browser-only workspace with sample identities and records, separate from live company data.']
];
const sharedIssues=[
 ['Incorrect email or password.','Re-enter the issued email and password. Use Forgot password? with a valid email if needed.'],
 ['Inactive / unauthorized profile','Contact Admin to verify account status and Auth linkage. A successful Auth login alone does not grant application access.'],
 ['Access restricted','Use Return to your workspace. Changing the URL does not provide a missing permission.'],
 ['Unable to load this screen','Use Retry after checking the connection. A module download failure is different from a database configuration failure.'],
 ['Saved successfully, but the updated records could not load.','Refresh and check the original reference before any new submission. The save may already have committed.'],
 ['Unable to sync changes. Retrying automatically…','The active page retries on focus, reconnect and roughly every 30 seconds while visible. Keep drafts and compare refreshed records before acting.'],
 ['This record is unavailable or your account no longer has access.','Refresh the activity list. The record may have changed or be outside your role/ownership scope.'],
 ['Projects needs a database configuration update.','Report the message to the system maintainer. Repository deployment notes identify project_history as a required dependency. Do not rerun legacy setup scripts as an end-user workaround.']
];
const admin={stem:'SiteTrace_Admin_User_Manual',title:'SiteTrace Web Application — Administrator User Manual',subtitle:'Administrator operations, accountability and monitoring',audience:'Admin',date,version,blocks:[
 H('Document control',1),T(['Item','Value'],[['Version',version],['Prepared',date+' · Asia/Manila'],['Audience','Active Admin accounts'],['Basis','Current local repository, source and isolated browser review'],['Scope','14 primary modules; authentication and account access are cross-cutting functions'],['Companion','SiteTrace_Engineer_Architect_User_Manual; SiteTrace_System_Module_and_Role_Review.md']]),...common,
 H('Chapter 1 — Introduction',1),H('1.1 Purpose and scope'),P('SiteTrace/MCPA tracks construction equipment, accountable holders, projects, requests, physical handovers, returns, damage, loss and consumable stock. Admin registers and maintains inventory metadata, assigns project accountability, reviews equipment requests, releases approved stock, resolves repair and missing cases, manages company access and reviews purchasing and monitoring records.'),
 P('The system is a plain HTML, CSS and JavaScript application backed by Supabase Auth, PostgreSQL database functions, row-level security, private Storage and a Deno Edge Function for account creation. Daily operation should use the deployed company address and an active Admin identity.'),
 H('1.2 Responsibilities and role boundaries'),P('Admin coordinates approval and oversight. The named Engineer or Architect inspects and confirms receipt; Admin cannot receive transfers, create routine field requests, submit returns, withdraw requests, cancel reservations/handovers, refuse damage or reopen field handovers through the current action map. Resolve physical custody through the responsible field account instead of editing metadata to imitate a movement.'),
 T(['Role','Implemented responsibility'],[['Admin','Company oversight, inventory metadata, Projects writes, request approval/rejection/release, repair completion/recovery, materials, purchase ledger, reports and access management.'],['Engineer / Architect','Same permissions: request available tools for assigned projects; transfer, receive, return and report issues within ownership constraints.'],['Secretary','Material Requests, Purchases and Settings; no equipment monitoring.'],['Tool Handler','Company equipment/project monitoring and dispatch of eligible available stock without a holder; no Admin approvals or field receipt/return actions.']]),
 H('1.3 Access requirements'),L(['A modern browser with JavaScript enabled and access to the company application and configured Supabase services. Chrome was used for the local screenshots; no cross-browser or mobile-hardware certification is claimed.','An issued active account and working Internet for company data. Offline demo cannot manage company accounts, consumables or purchases.','HTTPS or localhost and camera permission for field QR scanning; Admin monitors handovers rather than scanning to accept custody.','Allow popups/printing when using inventory Export or equipment tag printing. Private images and receipts require authorized Storage access.']),source('index.html; js/auth.js; js/permissions.js; supabase/functions/manage-accounts/handler.mjs.'),
 H('Chapter 2 — Getting Started',1),H('2.1 Login and first access'),loginProcedure,F('shared-login.png','Welcome back sign-in screen. Local capture; credential fields are empty.'),setupProcedure,
 H('2.2 Understand the Dashboard'),P('Dashboard opens Movement overview. Company equipment totals count quantities across records, rather than just the number of rows. The page includes Total Equipment, Available, Deployed, Active Projects, Equipment status, Equipment by project / site, Asset movement, Current inventory, Next actions, Recent asset activity, Active Projects and Custody overview.'),P('Needs Review links to Tool requests, Transfers in progress, Repair cases and Missing cases. Select a KPI or Open to go to the corresponding module. The current inventory preview shows at most six records; View full inventory opens Equipment Tracking. Asset movement charts count saved events during the last seven days in Manila time.'),availability,F('admin-dashboard.png','Admin Movement overview and sidebar, with isolated training records.'),
 H('2.3 Navigation guide'),T(['Sidebar section','Menu labels and purpose'],[['Overview','Dashboard — monitoring and action queues.'],['Assets','Equipment Tracking — registered tools; Projects — project metadata and inventory.'],['Movement','Requests; Transfers; Returns; Repairs; Missing.'],['Materials','Material Requests — opens the page headed Consumables.'],['Records','Purchases; Reports — opens Inventory monitoring; Activity Logs.'],['System','People & Accountability; Settings — opens My account.']]),P('Use the sidebar to change modules. On narrow screens, use the navigation menu button to open the drawer and select a module. Top search opens Equipment Tracking with your query applied; use View or Details on a matching row. The bell opens Notifications for roles authorized for Activity Logs. The Account menu contains My Account, Change theme and Log Out.'),accountProcedure,F('shared-account.png','My account controls under an Admin fixture identity.'),
 H('Chapter 3 — Administrator Modules and Features',1),H('3.1 Equipment Tracking'),P('The Admin table shows Asset ID, Item, Category, Brand, Location, Status, Condition, Acquired and Actions. Use search for ID, item, brand, serial, project or holder; combine Project, Category and Status filters; use Prev, numbered pages and Next. View opens Tool Information. Edit opens the metadata form. + Add Item registers an item; Export opens a printable filtered receipt.'),P('Equipment pictures support JPEG, PNG and WebP up to 5 MB, using configured private Storage and authorized image reads. Asset IDs are generated during save. The profile displays an equipment tag QR through an external QR service and offers printing. The Admin profile’s Movement History currently shows a registration entry only; use Activity Logs or the movement modules for actual saved transactions.'),P('Row selection currently offers Review repairs, Review transfers and Cancel Selection after JavaScript initialization. These navigate to the review modules. They do not bulk-change status or location. Legacy HTML labels and old bulk modal functions must not be treated as operational reassignment tools.'),F('admin-inventory.png','Admin Equipment Tracking table and filters.'),F('admin-add-item.png','Add New Item dialog. The displayed form is unsaved.'),source('1-admin/modules/masterlist/masterlist.js: initMasterlist, showToolProfile, setupMasterlistListeners, printQRTag, exportMasterlist; js/equipment-photos.js; migration 202610100003_feature_storage.sql.'),
 H('3.2 Projects'),P('Projects stores project name, location, one accountable Engineer/Architect profile, free-text phase, project status, completion percentage and last inventory-check date. One person can be assigned to multiple projects; a project has one accountable person. There is no multi-member assignment table or separate project membership editor.'),P('Use Scope (My projects or All projects), Search projects and Include archived projects. Open a project card to see Project Inventory, accountability, Last Inventory Check and Last Movement. Review Assigned Tools includes zero-quantity records; the operational Project Inventory hides them. Project History is a metadata audit; View movement history → opens movement records. Assignments are read-only in these inventory views.'),P('Admin can Add Project, Edit Project, Archive Project and Restore Project. Archiving preserves inventory assignments and history; it does not move equipment, clear holders or complete returns. Project History and Engineer/Architect Projects require the project_history dependency. Existing deployment notes record a missing-history issue; this task did not verify its live resolution.'),F('admin-projects.png','Projects list in the isolated environment.'),F('admin-project-form.png','Add Project fields and accountable-profile selection.'),source('1-admin/modules/sites/sites.js; supabase/migrations/202610100001_engineer_portal.sql; 202610100002_project_history.sql.'),
 H('3.3 Requests and reservations'),P('Requests is the equipment approval queue. Admin reviews Pending review records, uses Approve request or Reject request with a reason, then Release tools & create transfer for Approved records. Approval reserves all selected whole asset records. Release creates the linked transfer and code; it does not assign custody to the receiver. Reservations are part of Requests and Transfers, with no separate Reservations menu.'),F('admin-requests.png','Requests queue with current saved statuses.'),F('admin-request-review.png','Pending request detail and Admin approval/rejection controls.'),F('admin-release.png','Approved request and release control.'),
 H('3.4 Transfers and receipt confirmations'),P('Admin has History in Transfers. Search movement records, filter by status and use View to inspect sender, receiver, destination, transfer reference and saved inspections. Admin can copy the handover code from transfer details. The receiving field account performs testing, notes damage/missing items and confirms receipt. Your receiving QR, Send Transfer and Receive Transfer are field-role interfaces; they are not Admin receipt actions.'),P('A refusal is available only to eligible named field receivers. Refusing any damaged item holds the entire transfer, including the other tools, with existing custody and reservations. Admin monitors the refusal and contacts the accountable sender/requester. Cancellation or reopening is not an Admin action.'),F('admin-transfers.png','Admin Transfers History view.'),
 H('3.5 Returns, Repairs and Missing'),P('Returns lists the recorded return, returner, destination, notes and per-tool conditions. Field users save returns directly. There is no scheduling, separate handover QR, pending-return approval or Admin Confirm return action. Good returns clear the holder and set Available status; damaged returns open repairs and retain the holder until the appropriate resolution; missing returns retain existing custody/location and open a missing case.'),F('admin-returns.png','Returns review page with a locally seeded completed return.'),P('Repairs lists Reported, Under repair and Completed cases. Admin starts a Reported repair and completes an Under repair case with destination and completion notes. Missing lists Missing and Recovered cases. Admin records recovery with condition and location; damaged recovery opens a repair case. Reports from receipt and return inspection appear here as well as reports submitted by field users.'),F('admin-repair.png','Under repair completion fields.'),F('admin-recovery.png','Missing case recovery fields.'),source('js/movement-ui.js: createForm, renderDetail, submit; js/movement-cloud.js; 1-admin/modules/movements/setup.sql; supabase/migrations/202610060002_recipient_identity.sql and 202610100004_movement_cancellation.sql.'),
 H('3.6 Material Requests / Consumables'),P('The sidebar label Material Requests opens Consumables. This module manages bulk material stock, minimum levels, purchase alerts and consumable Purchase Requests. Admin and Secretary have access. Equipment requests use the separate Requests module. Consumable requests have no implemented Admin approval/rejection stage: creation, partial/full receipt and cancellation are the supported stages.'),P('Stock levels show Out of Stock, Low Stock or OK. Use Search consumables and Stock status; Purchase Requests has a separate Request status filter. Only one Pending or Partially Received purchase request is permitted per consumable. Quantity supports up to three decimal places. Stock History records opening stock, usage, restock, correction and request receipt.'),F('admin-materials.png','Material Requests / Consumables inventory and purchase-request table.'),F('admin-material-request.png','Consumable Purchase Request dialog; submission does not itself change stock.'),
 H('3.7 Purchases'),P('Purchases is a record-only ledger for Admin and Secretary. It records supplier, Invoice / Reference, purchase date, one optional Material Request, purchased item descriptions/quantities/prices, optional receipt and notes. Amounts display in PHP. Purchase history preserves prior and new values. Saving a purchase does not receive stock, approve a request or create equipment.'),P('Delivery status follows the linked consumable request. Use View to see items and Purchase history; Open Material Requests goes to the stock receipt workflow. Open private receipt is available only when a receipt is attached. PDF, JPEG, PNG and WebP receipts may be up to 10 MB; an authorized link lasts five minutes. There is no purchase delete or ledger-export control.'),F('admin-purchases.png','Purchases ledger and linked delivery status.'),F('admin-purchase-form.png','Record purchase dialog and line-item fields.'),source('1-admin/modules/consumables/consumables.js and setup.sql; 1-admin/modules/purchases/purchases.js; migrations 202610100005_purchase_ledger.sql and 202610100003_feature_storage.sql.'),
 H('3.8 Reports, Activity Logs and Notifications'),P('Reports opens Inventory monitoring, with Current inventory, Saved inventory snapshot and Movement history. Current inventory reflects now; selecting past From/Until dates does not turn it into historical inventory. Saved snapshots record real observation times and are not reconstructed for earlier dates. Movement history filters actual saved events. Export CSV downloads the selected non-empty report.'),F('admin-reports.png','Inventory monitoring report controls and current inventory.'),P('Activity Logs lists saved movement action, reference, actor, timestamp, tool IDs and summary. Search activity filters the visible authorized history. A reference link opens the exact transaction when available. Export CSV downloads the authorized movement activity; this is not a combined audit of accounts, project edits, purchases and consumable stock.'),F('admin-activity.png','Activity Logs with transaction references and CSV export.'),P('The bell opens recipient-specific Notifications and a Currently overdue list. Open and mark read changes only the selected notice’s read state and opens its authorized target. Overdue notices concern received requests with a needed-until date whose accepted equipment is still held under that request’s latest receipt. Weekly equipment review and inventory capture target Monday at or after 16:00 Asia/Manila, but require a trusted backend scheduler. In-app notices are implemented; no operational SMS, push or scheduled report email was confirmed.'),F('admin-notifications.png','Notifications interface. The empty local notice list is a real captured state.'),source('js/monitoring.js; 1-admin/modules/reports/reports.js; js/movement-overview.js; supabase/migrations/202610100006_monitoring.sql.'),
 H('3.9 People & Accountability and Settings'),P('People & Accountability is restricted to Admin. Find a person searches name, email or role. Rows show Person, Email, Role, Status, Account and Actions. Edit access changes role/status, while preserving person identity and accountability history.'),P('Add Account is a visible form for a new or existing company profile. Enter Full name, Authorized role, Supabase Auth user ID and Account status. Create the sign-in account in Supabase Authentication > Users first for active access; an inactive profile can be saved without a sign-in link. Existing Auth links cannot be reassigned through this form. Account access history loads recent changes. No account deletion or general personal-profile editing interface is implemented. Edit access can retain an existing Admin, but a non-Admin row has no Admin promotion option.'),P('Development / Testing Only appears only when that capability is enabled. It can create Engineer/Architect test accounts without email. These are real logins with access to live company records; the feature is not the browser-only offline demo. Its visibility depends on the server configuration.'),F('admin-people.png','People & Accountability with the restored Add Account form; synthetic local identities.'),source('1-admin/modules/users/users.js; 1-admin/modules/settings/settings.js; migrations 202610060001_account_management.sql and 202610060003_development_accounts.sql; supabase/functions/manage-accounts/handler.mjs.'),
 H('Chapter 4 — Step-by-Step Operational Procedures',1),P('The following procedures describe source-supported company operations. They were inspected and cross-checked against the genuine local UI; the capture browser did not execute their writes. Confirm the physical facts and current record state before using them in an authorized workspace.'),
 O('4.1 Find and review equipment','Check a tool’s identifying data and current status.','Admin; Equipment Tracking must load.', ['Select Equipment Tracking. Type an asset ID, item name, brand, serial number, project or holder in the search field.','Choose Project, Category and Status filters as needed. Use Prev or Next for additional rows.','Select View beside the correct asset. Review Tool Information, photo, holder, location, quantity and condition.','Use ← MASTERLIST to return. Open Activity Logs or a relevant movement module for full saved movement evidence.'],'The correct asset profile is displayed without changing equipment.','The profile’s registration-only Movement History is not a full transaction history. Equipment with positive quantity may still be reserved or unusable.'),
 O('4.2 Add an inventory item','Register new equipment metadata.','Active Admin; required equipment table policies and private Storage for a photo.', ['Select Equipment Tracking > + Add Item.','Enter Item Name / Classification and select Category. Optionally enter Brand, Model and Serial Number.','Select Initial Condition and Tracking Type (Individual or Bulk). For Bulk, enter Quantity and select Unit; use Sets for set-based records if that matches the physical count.','Optionally enter Identifying Details and choose an Item photo. JPEG, PNG or WebP must be non-empty and no more than 5 MB. Review the photo preview.','Select Save Item. Wait for completion and check the returned asset ID in the inventory.'],'A generated T- asset ID identifies the new item, registered with AVAILABLE status and no holder/project. The list refreshes.','Initial Condition is metadata; choosing Damaged does not create a repair transaction or automatically change AVAILABLE status. Review usability before issue. Photos require Storage configuration. A failure keeps the form/photo; a verified save followed by refresh failure requires checking the saved asset before retry.'),
 O('4.3 Edit metadata or replace an equipment photo','Correct identification without bypassing custody.','Admin; an existing asset.', ['Find the row in Equipment Tracking and select Edit.','Update the name, category, brand, model, serial, condition, tracking type, quantity/unit or identifying details as needed.','Select a replacement photo only if required. Keep current photo discards an unsaved replacement; the current attachment is kept when no new file is selected.','Select Update Item and verify the refreshed row.'],'The same asset ID remains; the selected metadata and optional photo are saved.','The editor does not change current_holder_id, site_id or status. No delete/remove-current-photo operation is provided. Quantity/type edits affect totals; verify the physical record and prefer traceable movement procedures for custody changes.'),
 O('4.4 Print a filtered inventory list or an asset tag','Produce a physical identification or review document.','Admin; printer/Save as PDF support, popups allowed; external QR service for a tag.', ['For an inventory list, select Equipment Tracking and apply the intended filters, then select Export.','Review the printable Tools & Equipment Receipt and use the browser print dialog or Save as PDF. This export includes all filtered rows, not just the visible page.','For an equipment tag, open View and use Print Tag in the profile. Check the printed asset ID against the physical item.'],'A printable filtered receipt or equipment-identification tag is produced.','Inventory Export is print output, not CSV. The print receipt’s footer currently says Fieldmark Asset Management System. QR images need api.qrserver.com; blocked images can prevent tag printing. QR image retrieval was unavailable in the capture session.'),
 O('4.5 Add or edit a project','Maintain project metadata and the accountable profile.','Admin; existing accessible Engineer/Architect profile; Projects database dependencies.', ['Select Projects > + Add Project, or open a project card and select Edit Project.','Enter Project Name and Location. Select the actual Engineer / Architect. One project has one accountable person.','Enter optional Project Phase; select Status and enter Completion (%) as a whole number from 0 to 100.','Optionally enter Last Inventory Check, no later than today in Manila.','Select Create Project or Save Changes and verify the project card/detail.'],'The project is created/updated and installed audit triggers record metadata changes.','Duplicate names, blank required text, an inaccessible profile, invalid percentage or future check date are refused. A concurrent edit requires closing/reopening the form. Project assignment does not transfer existing equipment custody.'),
 O('4.6 Archive or restore a project','Control visibility while preserving accountability.','Admin; a saved project.', ['Select Projects and open the correct project.','Select Archive Project. Read that equipment assignments and full history remain; select Archive to confirm.','To restore, enable Include archived projects, open the archived project and select Restore Project, then Restore.'],'The project’s active flag changes and its history remains.','Archiving does not return or transfer equipment. New receiving QR/direct transfers require active receiving projects. Existing inventory must still be reviewed.'),
 O('4.7 Review project equipment and history','Inspect assignments and supporting evidence.','Admin; readable project/equipment/history records.', ['Open Projects and the relevant project card.','Review Project Inventory. Select Review Assigned Tools to include zero-quantity records and filter by equipment search/status. Close the dialog when finished.','Select Project History for metadata changes; use View movement history → for saved movements.','For an equipment row, select View → to open the appropriate equipment detail.'],'Read-only views show the selected project’s equipment and available history.','Review Assigned Tools cannot reassign equipment. Missing project_history is a configuration issue, not an invitation to reconstruct or edit old history.'),
 O('4.8 Approve or reject an equipment request','Review the need and allocate eligible stock.','Admin; Pending review request and still-available, unheld, unreserved equipment.', ['Select Requests. Search movement records or filter status to find Pending review.','Select View on the request. Review Requested by, destination, purpose, needed-until date and tool IDs.','To approve, select Approve request. To reject, enter Reason for rejection and select Reject request.','Check the new status in the saved record and the requester’s recorded reason where applicable.'],'Approval changes the request to Approved and reserves the whole selected records. Rejection changes it to Rejected without custody assignment.','Approval is not a receipt. Competing approvals may fail if stock became reserved. The request cannot be silently edited or reallocated to different tools in this dialog.'),
 O('4.9 Release approved tools','Create a recorded handover for approved stock.','Admin; Approved request with intact reservations and an active operational receiver.', ['Select Requests and open the Approved record.','Confirm physical readiness, selected tool IDs, destination and named receiver.','Select Release tools & create transfer.','Record the resulting Handover code and select Open transfer to review it. Share the code with the named receiver using your authorized work process.'],'The request becomes Released and a pending transfer reserves the tools for receipt.','Release leaves current custody unchanged. Admin does not confirm the receiver’s testing. Cancellations after release belong to eligible field users and preserve history.'),
 O('4.10 Monitor a transfer, refusal or receipt','Track handover completion and condition evidence.','Admin; Transfers access.', ['Select Transfers > History. Search by reference, tool, person or project and choose a status if needed.','Select View on the transfer. Review Sent by, Receiver, Destination, code and the saved inspection information.','Use Copy handover code if coordination requires the reference.','For Awaiting receipt, contact the named receiver; for Damage refused · awaiting sender, coordinate with the accountable sender/requester; for Inspected / completed, review Recorded condition.'],'The actual saved handover state is understood; no custody changes occur from monitoring.','Admin has no receive/refuse/cancel/reopen controls. Do not use inventory edits to simulate a completed handover. Accepted damage may complete the transfer while opening a repair case.'),
 O('4.11 Review equipment returns','Verify return records and route damage/loss follow-up.','Admin; a saved return.', ['Select Returns. Find the return by reference, tool, person or destination.','Select View and inspect Returned by, destination, notes and Recorded condition for every tool.','Open Repairs or Missing to review any resulting cases. Compare current inventory holder/location with the recorded outcome.'],'The saved return and generated follow-up cases can be reviewed.','There is no Admin acceptance button or separate pending-return status. A damaged return retains its holder; a missing item retains source custody/location until resolution.'),
 O('4.12 Start and complete a repair','Move a reported case through repair and restore service.','Admin; Reported case for start, Under repair case for completion.', ['Select Repairs, locate the case and select View.','For a Reported case, select Start repair. Confirm its case status is Under repair.','When work and checks are complete, reopen the Under repair case. Select Available at project and enter Repair completion notes.','Select Complete repair and verify the case and inventory.'],'The case becomes Completed; the tool status becomes Available, the holder is cleared and the selected destination is recorded.','Start repair changes the report state; the raw equipment status may remain REPAIR. The destination-based availability caption may still say Unavailable for Available equipment at a project. Changed/closed cases require refresh.'),
 O('4.13 Record recovery of missing equipment','Restore a found tool with an inspected condition.','Admin; Missing case and physically inspected recovered equipment.', ['Select Missing and View the case.','Select Recovered at project and Recovered condition: Good — available for use or Damaged — send for repair.','Enter Recovery details explaining where/how it was found.','Select Confirm recovery and verify the resulting case, inventory and any new repair report.'],'The missing case becomes Recovered, holder is cleared, destination is recorded, and status becomes Available or For repair. Damaged recovery opens a repair case.','Recovery does not prove who caused the loss/damage. An already changed equipment status or closed case is rejected.'),
 O('4.14 Add or edit a consumable','Set material identity and minimum stock.','Admin or Secretary; Material Requests access.', ['Select Material Requests, which opens Consumables. Select + Add Consumable.','Enter Item name, Unit, Minimum stock and actual Opening stock. Quantities may have up to three decimal places.','Select Add Consumable. To change an existing name/minimum, use Edit and Save Changes.'],'The material appears with its opening-stock history and computed stock status.','Unit is read-only during edit. Current quantity changes belong in Update Stock or Receive Stock. Duplicate normalized names and invalid quantities are refused.'),
 O('4.15 Record usage, restock or a physical-count correction','Keep consumable stock and history accurate.','Admin or Secretary; existing item and a physical quantity/reference.', ['Select Material Requests > Update Stock on the correct item.','Choose Change type: Record usage, Restock without a request, or Correct physical count.','Enter Quantity used, Quantity added or Correct total stock as displayed. For correction, enter the resulting total, not a signed difference.','Enter Reason / reference and inspect Stock after change.','Select Save Stock Change; review the balance and History.'],'Usage subtracts; restock adds; correction sets the stated total. A stock movement records the reason and resulting balance.','Usage cannot exceed current stock. Use Receive Stock for deliveries belonging to an open request; recording the same delivery here and there would double-count it. Quantity changes are version checked.'),
 O('4.16 Create a consumable Purchase Request','Record material stock required from purchasing.','Admin or Secretary; consumable without a Pending/Partially Received request.', ['Select Material Requests > + Purchase Request, Request Stock or Purchase Required on an item.','Select Consumable and enter Quantity requested. Review the suggested shortage; adjust to the actual need.','Optionally enter Needed by, not in the past. Enter Requested by and Purpose.','Select Submit Request and review the new CR- reference in Purchase Requests.'],'A Pending purchase request is saved; available stock stays unchanged.','Requested by is entered text rather than proof of a field account. There is no approval/rejection step. One open request per consumable is enforced.'),
 O('4.17 Receive partial/full material deliveries or cancel the remainder','Update stock from actual deliveries and preserve purchasing history.','Admin or Secretary; Pending or Partially Received purchase request.', ['In Material Requests > Purchase Requests, select Receive Stock on the correct CR- record.','Enter Quantity received greater than zero and no greater than the outstanding amount. Enter Delivery reference / notes.','Select Confirm Receipt; check the stock balance and request status. Repeat for later actual partial deliveries.','To close an unfulfilled remainder, select Cancel or Cancel Request, enter Cancellation reason and select Confirm Cancellation.'],'Received stock increases immediately. The request becomes Partially Received or Received. Cancellation closes the outstanding amount and retains earlier receipts.','Cancellation does not reverse stock already received. Saved receipts with a list-refresh failure must be checked before re-entry.'),
 O('4.18 View consumable Stock History','Reconcile stock against supporting records.','Admin or Secretary; existing material.', ['Select History on a consumable, or Stock History in its Purchase Request detail.','Review Date, Change, Quantity, Balance and Reason / Reference. Dates use Manila time.','Match request-receipt entries with the correct CR- reference, then Close.'],'The saved stock movements explain the balance.','The interface does not offer a stock-history export/delete/edit control. Use explicit future correction entries for verified count changes.'),
 O('4.19 Record or edit a purchase','Store an invoice record independently of physical receipt.','Admin or Secretary; configured purchase ledger; private receipt Storage if attaching a file.', ['Select Purchases > Record purchase, or Edit an existing row.','Enter Supplier, Invoice / Reference and Purchase date. Optionally select Material Request.','For each Purchased item, enter Item description, positive Quantity (up to three decimal places) and Unit price (PHP) (up to two decimal places). Use Add item or Remove item; at least one and no more than 100 lines are allowed.','Optionally attach Receipt / Invoice (PDF/JPEG/PNG/WebP, up to 10 MB) and enter Notes. Review Total.','Select Save purchase and verify the ledger row.'],'The purchase and append-only history are saved. Linked delivery status follows the consumable request.','Saving never increases stock. A duplicate supplier/reference/date is refused. A changed purchase requires reopening before save. The current receipt is retained unless replaced.'),
 O('4.20 Review a purchase, its private receipt and linked delivery','Inspect purchase evidence and continue to materials receipt.','Admin or Secretary; readable purchase and attached receipt where applicable.', ['Select Purchases, set Search purchases and date filters if needed, then View the correct PUR- row.','Review supplier/reference, items, total, notes, Delivery and Purchase history.','Select Open private receipt if attached; allow the popup and retrieve it before the short-lived link expires.','Select Open Material Requests to record an actual delivery through Receive Stock.'],'The ledger evidence is displayed and any delivery is recorded in the correct stock workflow.','An attachment is not proof of delivery. Private receipt URLs expire after five minutes. Ledger deletion/export and receipt removal without replacement are not offered.'),
 O('4.21 Load monitoring reports and export CSV','Review present inventory or saved historical observations.','Admin; monitoring report RPC and actual snapshots if requesting history.', ['Select Reports. Choose Current inventory, Saved inventory snapshot or Movement history from Report.','Enter From and Until; choose a valid inclusive range no longer than 367 days and select Load report.','For Saved inventory snapshot, select the actual Saved snapshot capture time.','Read the scope message, then select Export CSV if data rows are available. Open the mcpa-current, mcpa-history or mcpa-activity CSV file.'],'The chosen report is displayed/exported with the documented scope.','Current inventory always describes now; date filters apply to snapshots/history. Empty periods cannot be exported. No prior snapshot is invented when historical captures are absent.'),
 O('4.22 Review activity and notifications','Follow recorded actions to their supporting transactions.','Admin; Activity Logs and configured monitoring.', ['Select Activity Logs and use Search activity. Select a linked action/reference to open its exact saved record.','Select Export CSV to download the authorized movement activity when needed.','Select the topbar bell. Review Currently overdue and saved notices.','Select an overdue request reference to inspect it, or Open and mark read on a notice to update that notice’s read state and open its authorized module. Close the dialog when done.'],'Movement links resolve to records; selected notice read state persists when the server confirms it.','Activity Logs does not include all module-specific audits. Scheduled weekly/overdue notices depend on a backend scheduler. Opening the bell alone does not mark every notice read.'),
 O('4.23 Add an account or update an existing company profile','Create company access while preserving accountability identities.','Admin; existing verified Auth user ID for active sign-in access.', ['Select People & Accountability > Add Account. The account form is visible on the main page.','Keep New company profile selected and enter Full name and Authorized role. To update a person, select their Company profile instead.','For active access, create or verify the person in Supabase Authentication > Users, copy their user ID into Supabase Auth user ID and select Active. You may instead save an Inactive company profile without an Auth link.','Select Add Account for a new profile, or Save account access for an existing one. Confirm the saved row. Existing linked Auth IDs cannot be reassigned.','For a quick role/status change, use the row Edit access action. Load Account access history to review recorded changes.'],'The account is saved through the existing account-management RPC. The form remains available when the optional test-account service is unavailable.','Active access requires a valid Auth link. The server prevents removing your own Admin access, reassigning a linked Auth identity or promoting a new Admin. This form does not create Auth credentials or send email.'),
 O('4.24 Use development accounts only in authorized testing','Create a controlled test login when email-based onboarding is unavailable.','Admin; explicitly enabled Development / Testing Only capability; approved isolated/staging use.', ['In People & Accountability, locate Development / Testing Only if shown.','Enter distinct test Full name, testing Email, Temporary password of 12–128 characters and Role (Engineer or Architect).','Select Create test account. Keep the password privately; do not capture it in documentation.','If creation is unfinished, use the corresponding Retry control and original details/password. When testing ends, deactivate the account in Edit access.'],'A real test Auth login is created without sending email; repeated completed creation retains its original account/password.','These accounts can access company records. They are not offline demo identities. Do not create test accounts in production merely to obtain screenshots. This procedure was not run during documentation.'),
 source('Procedures 4.1–4.25 follow the module handlers cited in Chapter 3, js/permissions.js, and the authenticated, identity, account-management, portal, cancellation, ledger and monitoring migrations.'),
 H('Chapter 5 — Common Issues and Troubleshooting',1),T(['Message / symptom','Action'],[...sharedIssues,['Movement storage is not configured.','Ask the system maintainer to verify the current authenticated movement installation; refresh after configuration is completed.'],['A tool is reserved by an approved request or pending transfer.','Open the owning request/transfer and coordinate with the eligible field user. Do not clear assignments manually.'],['Purchase setup / Monitoring setup is not installed.','Report the configuration message and module. A visible menu does not establish that its deployed database functions exist.'],['Photo or private receipt could not load/upload','Check permitted format/size, network, Storage access and popup permissions. Confirm the intended asset/purchase before retrying.'],['Unexpected Available / Unavailable display','Read both status and location availability; inspect reservations/holder and eligibility. The helper is not a complete issue-readiness check.'],['Counts differ from the number of rows','Dashboard/project totals sum quantities, zero-quantity records may be hidden, and inventory previews show only six rows.'],['No saved historical snapshots','Historical capture begins prospectively. Ask the maintainer to verify scheduler installation; use actual movement history without inferring past inventory.']]),
 H('5.1 Frequently Asked Questions'),O('Can Admin confirm equipment receipt?','Clarify the custody boundary.','Admin.',[],'No. Only the named receiving Engineer/Architect has receiveTransfer and the inspection form. Admin monitors the saved receipt.','A legacy backend error string mentioning Admin is not the current permission gateway.'),P('Can Admin cancel a reservation or refused handover? No. The current cancellation migration restricts these actions to eligible accountable Engineer/Architect accounts. Admin approval/rejection/release remains supported.'),P('Does a purchase change stock? No. Record the actual delivery in Material Requests > Receive Stock. Does a consumable Purchase Request need approval? No separate approval stage is implemented.'),P('Does archiving a project return its equipment? No. Archiving changes project visibility/active state while retaining inventory and history.'),P('Can I edit a historical transaction? No historical editor is provided. Use an authorized follow-up action, new request or future stock correction and preserve the original record.'),
 H('Chapter 6 — Administrator Best Practices',1),L(['Verify physical stock and tool condition before approving/releasing. A database record or printed tag does not prove a tool is ready or physically present.','Keep role assignments narrow and review active access regularly. Select existing company people to preserve permanent accountability identities.','Assign the actual receiving Engineer/Architect to an active project before direct transfer. Do not replace one person’s project assignment merely to imitate multi-person membership.','Track pending/refused handovers through the original reference. Ask the named receiver to inspect every tool; do not claim that release or QR scanning completed custody.','Use Repairs and Missing for resolution; keep damage descriptions factual. Acceptance/refusal records do not determine who caused damage.','Reconcile consumable stock against History and purchase deliveries. Use correction with a reason for a verified physical-count discrepancy and avoid double-counting requests/ledger receipts.','Check successful-save messages before retrying a form after network loss. A failed refresh may follow a committed transaction.','Review weekly snapshots by actual capture time and follow up on overdue equipment. Treat scheduler and email deployment as maintainer prerequisites, not ordinary user operations.','Protect private receipts, personnel details and passwords in exports/screenshots. Sign out fully from shared devices.']),
 H('Glossary',1),T(['Term','Meaning'],glossary),H('Evidence, validation and revision information',1),P('The companion system review contains the five-role permission matrix, module inventory, implementation gaps, source references and capture manifest. Source and screenshot hashes were checked against the completed artifacts. The captured states demonstrate role-correct rendering; they do not certify production deployment or execute all write procedures.'),T(['Version','Date','Revision'],[[version,date,'Initial source-based Administrator manual; genuine isolated screenshots; deployment and hardware limits identified.']]),P('Future revision: repeat source/permission review after any workflow, label, migration or role change. Replace the corresponding figures using dedicated staging accounts and approved records. Do not reuse production transactions merely to illustrate a procedure.')
]};
const engineer={stem:'SiteTrace_Engineer_Architect_User_Manual',title:'SiteTrace Web Application — Engineer and Architect User Manual',subtitle:'Field equipment requests, transfers, inspection and returns',audience:'Engineer and Architect',date,version,blocks:[
 H('Document control',1),T(['Item','Value'],[['Version',version],['Prepared',date+' · Asia/Manila'],['Audience','Active Engineer and Architect accounts'],['Basis','Current repository; source and isolated browser review'],['Scope','10 authorized primary modules; identical role permissions'],['Companion','Administrator manual and SiteTrace_System_Module_and_Role_Review.md']]),...common,
 H('Chapter 1 — Introduction',1),H('1.1 Purpose and responsibilities'),P('SiteTrace/MCPA records the location, holder and condition of construction tools and materials. Engineer and Architect accounts request available equipment for assigned projects, coordinate transfers of equipment they hold, inspect equipment addressed to them, record returns and report damage/loss. The application uses permanent company profile IDs for accountability, even if names are duplicated.'),
 P('Engineer and Architect have the same route, action and backend ownership permissions. Only the displayed role label differs. Actual visible records depend on individual custody, requester/sender/receiver identity, active project assignment and current transaction state. An empty list for one Architect is not a different role policy.'),H('1.2 Access requirements'),L(['An issued active company account with a valid Auth-to-company-profile link and a modern JavaScript browser.','Working Internet to read/save company records; the correct existing project assignment for requests and new receiving/direct-transfer workflows.','HTTPS or localhost, a supported phone/browser camera and granted camera permission for optical scanning. Manual receiving details and handover-code entry are available alternatives.','Enough time to physically inspect and test every received non-missing tool before receipt. The application requires individual conditions and explicit damaged-custody decisions.']),P('Your company administrator manages accounts, project assignments, approvals, repair completion and missing recovery. You cannot add/edit inventory, edit projects, manage users, approve requests, complete repairs, confirm recovery, use Reports, Material Requests or Purchases. The presence of legacy files or a URL does not grant those permissions.'),source('js/permissions.js; js/auth.js; js/navigation.js; supabase/migrations/202610040001_authenticated_access.sql and 202610060002_recipient_identity.sql.'),
 H('Chapter 2 — Getting Started',1),H('2.1 Access and login'),loginProcedure,F('shared-login.png','Company sign-in screen; local capture with empty credential fields.'),setupProcedure,H('2.2 Dashboard and navigation'),P('Dashboard opens Movement overview with My assigned equipment, quantity-based equipment totals, project summaries, movement charts, incoming transfers, open requests, maintenance/missing alerts and custody indicators. Request Tools, Receive / Transfer, Return Tools and Report an Issue open the relevant modules. Use Open in Next actions or a linked recent activity entry for the supporting transaction.'),P('Dashboard inventory is a personal custody view, while project summaries and movement context use other authorized data. Equipment Tracking is specifically restricted to equipment whose current_holder_id matches your permanent company profile. Requests uses a separate eligible catalog so you can request available company stock. These scopes should not be treated as the same list.'),F('engineer-dashboard.png','Engineer dashboard and authorized sidebar with isolated records.'),F('architect-dashboard.png','Architect dashboard. Its role policies match Engineer; this fixture account has different assigned records.'),T(['Sidebar label','What you can do'],[['Dashboard','Monitor your custody and authorized action queues.'],['Equipment Tracking','Search and inspect equipment in your confirmed custody.'],['Projects','View projects assigned to your profile, their authorized inventory and history.'],['Requests','Submit equipment requests and follow approval/release; withdraw/cancel when eligible.'],['Transfers','Send Transfer, Receive Transfer and History; scan/enter codes, inspect and follow up.'],['Returns','Record a return for eligible held tools and review saved returns.'],['Repairs','Report held-tool faults and follow repair status.'],['Missing','Report held-tool loss and follow recovery status.'],['Activity Logs','Read/search/export authorized movement history.'],['Settings','My account identity, display mode and logout.']]),P('Material Requests appears in an old menu definition but is removed by the current permission filter for Engineer/Architect. Reports, Purchases and People & Accountability are also restricted. On phones/tablets, open the navigation drawer, select a module and use horizontal scrolling for wide tables if needed.'),accountProcedure,F('engineer-account.png','Engineer My account identity and preference controls.'),source('js/dashboard-view.js; js/movement-overview.js; js/app.js module selection; 1-admin/modules/settings/settings.js.'),
 H('Chapter 3 — Equipment Tracking',1),H('3.1 Your assigned equipment'),P('Equipment Tracking reads the narrow personal-equipment snapshot. It shows equipment in your confirmed custody and relevant authorized movement history. Equipment reserved for you or sent to you does not become personal custody until receipt. No equipment is currently assigned to you. is a valid empty state; go to Requests to request available stock, or Transfers to inspect an incoming handover.'),F('engineer-equipment.png','Personal Equipment Tracking for an Engineer fixture account.'),availability,
 O('3.2 Search equipment and open Details','Locate a held tool and review its accountable state.','Engineer or Architect; equipment in confirmed custody.', ['Select Equipment Tracking.','Enter a tool ID, name, brand, holder or related text in Search tools. Select Status and Project filters if helpful. Clear filters if an expected item is absent.','Select Details on the correct equipment row.','Review Current holder, Project, Status, Quantity and Movement history. Select Close to return.'],'The tool detail and authorized recorded events are displayed without changing custody.','Tools no longer in your custody leave the personal view. Incoming/reserved equipment belongs in Transfers/Requests; all-project equipment is not a personal assignment. A detail action such as Transfer only opens the module; it does not complete that action.'),F('engineer-tool-detail.png','Held tool Details and its authorized movement history.'),
 H('3.3 Status interpretation'),statuses,P('The equipment status vocabulary includes Available, In Use, For Repair, Under Repair, Missing and Disposed in the current views. Product planning text also mentions Borrowed, Transferred, For Return, Repaired and Sold, but separate user-facing lifecycles for those labels were not confirmed. Use saved request/transfer/report states to understand what actually happened.'),source('js/movement-overview.js: personal, detail, load; js/equipment-tracking.js; supabase/migrations/202610100001_engineer_portal.sql: mcpa_personal_equipment_snapshot.'),
 H('Chapter 4 — Equipment Requests',1),H('4.1 Request catalog and prerequisites'),P('Requests offers positive-quantity, Available equipment not already reserved or in a pending/refused transfer. The backend additionally refuses requests for equipment with a current holder. Ask the current holder to transfer an in-use tool rather than requesting it as available stock. Choose an existing destination assigned to your profile; the broad destination dropdown may show projects you cannot request for, so confirm assignment first.'),P('Selecting a tool moves the whole asset record and its quantity. There is no per-request partial-quantity field or bulk-record split. If the record represents a set or a bulk stock, coordinate the actual whole-record allocation with Admin.'),
 O('4.2 Create and submit an equipment request','Ask Admin to allocate available equipment for assigned project work.','Active Engineer/Architect; an assigned destination and eligible available, unheld stock.', ['Select Requests. In Request tools, use Search available tools to locate equipment by name, ID or project.','Tick the required records under Choose asset records. Check the displayed Qty (whole record) and selection count.','Choose Destination project. Optionally enter Needed until; if supplied, it must be a valid date not in the past in Manila.','Enter Purpose explaining the work, using at most 2,000 characters.','Select Submit request and wait for Request saved successfully.','Note the REQ- reference and open it in Your requests.'],'A Pending review request is saved for your identity; no equipment is received or assigned yet.','A Pending request does not reserve stock until Admin approves. Competing requests can exist; approval rechecks stock. Blank purpose, no selection, invalid date, unauthorized project or held/reserved stock is refused.'),F('engineer-request.png','Request tools form and request history; isolated catalog.'),
 O('4.3 Monitor approval, release and request history','Understand whether equipment is reviewed, allocated or awaiting receipt.','Requester or another account with authorized visibility.', ['Stay in Requests and use Search movement records and status filtering. Select View on the correct REQ- record.','Read Pending review, Approved, Rejected or Released. Review rejection reason when present.','For a Released request, review Handover code and select Open transfer.','Go to Transfers > Receive Transfer to inspect the physical handover before confirming custody.'],'The saved request explains approval and release; linked transfer details guide receipt.','Approved means reserved, not received. Released means a transfer exists. A saved request has no editable tool/date/purpose form or automatic resubmission control.'),
 O('4.4 Withdraw a pending request or cancel an approved reservation','Close your unfulfilled need while preserving the original history.','The original Engineer/Architect requester; Pending review for withdrawal, Approved without a transfer for reservation cancellation; cancellation migration installed.', ['Open the request in Requests.','If eligible, use Withdraw request or Cancel reservation in the record detail.','Enter Reason and tick I confirm this action for the displayed reference.','Select the matching action button and review the status/message.'],'Withdrawal saves Withdrawn. Reservation cancellation saves Canceled and releases allocation; custody is unchanged.','These controls disappear when state/ownership is ineligible. Once release creates a transfer, use the eligible transfer cancellation procedure. Admin cannot perform these new field cancellations. You cannot restore a withdrawn/canceled request; create a new request if still needed.'),F('engineer-withdraw.png','Pending request detail with requester withdrawal fields. No action is submitted.'),source('js/movement-ui.js: eligibleTools, createForm, adjustmentForm, submit; js/movement-cloud.js; migrations 202610060002_recipient_identity.sql and 202610100004_movement_cancellation.sql.'),
 H('Chapter 5 — QR Code Equipment Transfers',1),H('5.1 Distinguish the three QR purposes'),T(['Code / QR','Purpose','What it does not do'],[['Your receiving QR','Identify the active receiving person and their assigned active project before dispatch. Payload begins MCPA-RECEIVER:.','It does not create a transfer, reserve tools or accept custody.'],['Transfer handover QR / code','Identify the TRF- handover created after dispatch, for lookup and inspection by the named receiver.','It does not bypass inspection or make another person the receiver.'],['Equipment tag','Identify an asset ID. The handover scan path may match a unique pending handover addressed to you.','It cannot transfer ownership merely because it was scanned.']]),P('The receiving QR expires after 15 minutes. Generate My Receiving QR revokes older references for the same receiver; Revoke receiving QR invalidates the current reference. A valid QR can assist multiple transfers while valid, but each dispatch still checks the current account and project assignment. Transfer handover codes are saved references, not the 15-minute receiving tokens.'),
 O('5.2 Show your receiving QR to a sender','Provide a verified receiving identity and project before transfer creation.','Active Engineer/Architect assigned to at least one active receiving project; portal RPC and QR display library.', ['Select Transfers > Receive Transfer. Locate Your receiving QR.','Select Receiving project if more than one assigned active project is offered. For one project the selector is disabled.','Select Generate My Receiving QR. Show the displayed QR to the sender and verify the displayed name/project.','Check the expiry message. Generate a fresh code if it expires, or select Revoke receiving QR when it should no longer be used.'],'The sender can resolve the short-lived receiver/project context. No equipment custody changes.','No assigned receiving project. requires Admin to assign an active project. Generating a QR writes only its own ephemeral reference and revokes older ones. QR bitmaps and optical scanning were unavailable in this capture session; the genuine receiving interface is shown before generation.'),F('engineer-receiving.png','Receive Transfer: Your receiving QR, receiving-project selection, handover lookup and incoming transfers. No token was generated.'),
 O('5.3 Initiate a transfer with a receiving QR or manual details','Dispatch equipment currently held by you to the intended field receiver.','Active Engineer/Architect; positive-quantity In Use tools in your custody, no reservation/pending transfer; active receiving Engineer/Architect assigned to the active destination.', ['Select Transfers > Send Transfer. Choose Scan Receiver QR and ask the receiver to show their current receiving QR.','Grant camera permission and scan the receiving QR. Read Verified receiving account, name and project. If the library/camera is unavailable, choose Enter Details Manually instead.','For manual entry, choose Destination project and Receiving Engineer / Architect. Review the role/project descriptions; identify the exact person if names are duplicated.','Tick eligible records under Choose asset records and review whole-record quantities. Optionally enter Handover notes.','Select Create transfer. Record the returned TRF- reference and share the Handover code with the named receiver.'],'An Awaiting receipt handover reserves the selected records. Original custody remains until the named receiver inspects/receives or an eligible cancellation occurs.','Scanning only fills receiver/project. Submit rechecks active assignment and QR validity if used. Stale QR, mismatched name/project, changed assignment, held-by-other stock and reserved equipment are refused. Record dispatch before equipment leaves the source, in line with company process.'),F('engineer-send.png','Send Transfer with manual destination and receiver fields revealed. No transfer is created.'),
 O('5.4 View and share a transfer reference','Coordinate the saved handover with its named receiver.','Authorized sender/receiver; saved transfer.', ['Select Transfers > History. Search by reference, tool, person or project and filter status when needed.','Select View on the correct transfer.','Read the receiver/destination and use Copy handover code. When the QR display library is available, the same handover reference is rendered as a QR.','Share the reference only with the intended receiver through the approved work channel; ask them to inspect actual tools.'],'The named receiver can find the handover by its code.','Clipboard permissions may block copying; use the visible reference manually. An unavailable QR bitmap does not prevent manual code lookup. No messaging integration automatically sends the code.'),F('engineer-transfer-history.png','Transfer History and saved local transfer references.'),
 O('5.5 Find an incoming handover by code or scan','Open the saved transaction before recording receipt.','Named receiving Engineer/Architect; existing authorized handover.', ['Select Transfers > Receive Transfer.','Enter the sender’s exact code in Transfer code and select Find transfer. Alternatively select the incoming record’s inspection/view control.','If Scan Handover QR is available, grant camera access and scan the original handover QR or asset tag. Stop camera closes capture.','Confirm the saved receiver, destination, tools and current holders before proceeding to inspection.'],'The saved handover opens. No custody changes from lookup/scanning.','No transfer found for that code. requires the original reference and current company data. An asset-tag scan may show details only when no pending handover is addressed to you. Multiple pending matches require the transfer reference and Admin review. The manual lookup dialog can display an authorized record even when you are not its receiver, but it does not offer receipt permission.'),
 O('5.6 Cancel or reopen an eligible unreceived handover','Resolve an interrupted dispatch without rewriting history.','Engineer/Architect original field sender, or linked released-request requester for cancellation; original field sender only for reopening; eligible pending/refused state.', ['Select Transfers > History and View the handover.','Use Cancel handover if eligible and equipment has not been received. For a refused handover, the original field sender may instead use Reopen for receiver inspection.','Enter Reason, tick the displayed confirmation and select the matching action.','Review the new saved status and coordinate the physical tools with the receiver.'],'Cancellation saves Canceled, releases the reservation and leaves custody unchanged; a linked released request is also closed. Reopening returns the refused transfer to Awaiting receipt without changing custody/reservations.','Refused tools remain reserved until eligible follow-up. Completed receipt cannot be undone by cancellation. A request-linked Admin release can be canceled by its eligible field requester, but that requester is not the original Admin sender and cannot reopen it through the field-sender action.'),source('js/movement-ui.js: receivingProjects, generateReceivingQr, resolveReceivingQr, startCamera, transferLookup, renderDetail; migrations 202610100001_engineer_portal.sql and 202610100004_movement_cancellation.sql.'),
 H('Chapter 6 — Equipment Receipt Confirmation',1),H('6.1 Receiver responsibilities'),P('Inspect physical identity, quantity and condition against the saved tool list. Record each tool as Good — ready for use, Damaged — needs repair or Missing — not received. A non-missing item must be tested and explicitly marked I tested this tool. Damage/missing notes are mandatory. This interface has no inspection-photo upload or partial-quantity acceptance; it records a condition for each entire asset record.'),
 O('6.2 Inspect and confirm an incoming transfer','Accept accountability only for inspected equipment.','The named receiving Engineer/Architect; Awaiting receipt transfer with unchanged source custody/status/quantity.', ['Open the incoming transfer from Receive Transfer or History. Check Receiver, Destination, tool IDs and Current holder.','Under Inspect the handover, select Inspected condition for every tool. Physically test every non-missing tool and tick I tested this tool.','For damaged/missing items, enter factual Inspection notes (at most 2,000 characters per item).','For each damaged item, choose Custody decision for damaged equipment. Select Accept custody with recorded damage if you accept it. Missing items are not accepted into custody.','When no eligible damaged item is refused, select Confirm receipt of all inspected tools. Wait for Receipt confirmed. Custody and any repair or missing reports have been updated.','Review the saved Recorded condition, your Equipment Tracking and any Repairs/Missing follow-up.'],'Good items change to your holder/project and In Use. Accepted damaged items change to your holder/project and For repair, with a repair case. Missing items keep source holder/location, become Missing and open a missing case. The handover is Inspected / completed.','Every tool must be represented once; testing is not required for missing items. Receipt is blocked if source custody/status/quantity changed after dispatch or another action already completed the handover. Completion does not mean every item was physically received in good condition.'),F('engineer-inspection.png','Incoming transfer inspection dialog before any confirmation. QR bitmap was unavailable; the original code remains visible.'),F('engineer-inspection-confirm.png','Lower inspection form showing the required test checkbox and Confirm receipt of all inspected tools.'),
 O('6.3 Refuse eligible damaged equipment','Record a damage refusal and hold the handover for accountable follow-up.','Named Engineer/Architect receiver of an eligible pending handover: active field sender, or initial released request owned by this receiver; cancellation/refusal migration installed.', ['Open the handover and complete each tool’s condition, notes and non-missing test checks.','For at least one damaged tool, choose Refuse damaged handover under Custody decision for damaged equipment.','Enter Reason for refusing this handover and tick the refusal confirmation.','Select Refuse handover & notify sender and review the saved refusal status.','Contact the original sender/requester to resolve the physical handover and choose eligible cancellation or sender reopening.'],'The whole transfer becomes Damage refused · awaiting sender. All custody/status and reservations stay with their original source state, including the other tools; inspection evidence is saved.','Refusal is not a generic reject button for any transfer. A Tool Handler dispatch without an eligible linked request does not offer this refusal option. If unavailable and custody cannot be accepted, contact the sender/Admin before confirming. Refusal does not determine who caused damage and does not itself open an accepted-damage repair case.'),F('engineer-refusal.png','Actual damage-refusal form after unsaved condition selections. No refusal is submitted.'),
 H('6.4 Discrepancies and accountability'),P('For not-received equipment, choose Missing and explain the discrepancy; do not mark it Good to close the screen. Missing items retain the original custody/location while the missing case is recorded. For accepted damage, the receiver takes custody with the condition documented. The whole-record model cannot record receipt of only part of a quantity; resolve partial-quantity discrepancies with Admin before submitting an inaccurate whole-record inspection.'),source('js/movement-ui.js: conditionFields, readConditions, submit; supabase/migrations/202610060002_recipient_identity.sql: receipt updates; 202610100004_movement_cancellation.sql: refusal eligibility and immutable evidence.'),
 H('Chapter 7 — Equipment Returns',1),H('7.1 Which tools can be returned'),P('Returns is for positive-quantity In Use equipment held by your identity and not reserved for an approved request or pending/refused handover. The application does not maintain a separately scheduled For Return queue or return-specific QR workflow. Needed until dates and Currently overdue notices help you identify tools whose expected use period ended.'),
 O('7.2 Record a return and inspect its outcome','Record actual return condition and release good-tool custody.','Engineer/Architect current holder; eligible In Use tools; actual destination and physical return checked.', ['Select Returns. In Return tools, tick the records under Choose asset records. Review that each selection represents a whole record.','Choose Return destination from existing projects. Riverside Warehouse is only a preselection if that actual name exists; choose the real destination.','Select Inspected condition for every selected tool. Enter Inspection notes for damaged or missing tools. Optionally enter Return notes.','Select Confirm return only after the real handover/count is established under company procedure.','Read Return saved successfully., open the RTN- record and compare Recorded condition with current custody/status. Check Repairs/Missing when generated.'],'The return is saved immediately. Good tools clear the holder, move to the chosen destination and become Available. Damaged tools move to the destination, retain the existing holder and open repair cases. Missing tools keep source holder/location, become Missing and open missing cases.','There is no second Admin acceptance action. Damaged/missing tools do not automatically clear accountability. Returned good tools at a project may still show Unavailable by the location-based helper; read status, holder and eligibility together.'),F('engineer-return.png','Return tools form with a selected asset and per-tool condition fields.'),
 O('7.3 Review return history and unresolved accountability','Confirm the saved return and follow-up cases.','Authorized Engineer/Architect returner or readable related record.', ['In Returns, use Search movement records/status filtering and select View on the RTN- record.','Review Returned by, destination, notes and per-tool Recorded condition.','Check Equipment Tracking for tools still held and Repairs/Missing for pending resolution.','Use Activity Logs to inspect the original saved return and related events.'],'The recorded return and any continuing damaged/missing accountability can be reconciled.','Return records have no cancellation, edit, delete, scheduling or separate receipt-confirmation controls in the current interface.'),source('js/movement-ui.js: createForm, syncReturnConditions, submit; supabase/migrations/202610060002_recipient_identity.sql: createReturn and per-condition inventory updates.'),
 H('Chapter 8 — Other Authorized Operations',1),
 O('8.1 View assigned Projects and their equipment','Review project accountability and authorized inventory.','Engineer/Architect assigned to a project; project snapshot/history dependency installed.', ['Select Projects. Use Search projects and, if needed, Include archived projects. The page is limited to assigned projects.','Open the project card. Read Accountable Engineer / Architect, Equipment at Project, Last Inventory Check and Last Movement.','Select Review Assigned Tools to search/filter the project’s equipment including zero-quantity records.','Select Project History for authorized metadata history or View movement history → for movement records.','Close review dialogs and return to All Projects as needed.'],'The real accountable profile and permitted project equipment/history are visible.','Add/Edit/Archive/Restore controls are removed for field accounts. All projects cannot broaden the server scope. Project equipment may be held by someone else; it is not your personal custody. One project has one accountable person. The reviewed deployment note identifies a project_history dependency problem whose live fix remains unverified.'),F('engineer-projects.png','Assigned Projects for the Engineer fixture identity.'),
 O('8.2 Report tool damage or a repair need','Make an equipment fault visible for Admin resolution.','Engineer/Architect holder; eligible positive-quantity In Use tool without a reservation/pending transfer.', ['Select Repairs. In Report a repair, choose Tool.','Enter Damage / issue details, describing the fault and circumstances in at most 2,000 characters.','Select Submit repair report.','Open the saved REP- record to follow Reported, Under repair or Completed. Coordinate actual repair/release with Admin.'],'The tool becomes For repair, holder remains, and a reported repair case/activity entry is saved.','You cannot Start repair or Complete repair. Do not submit duplicate reports for an already locked/repair tool. No repair-image attachment, repair-cost editor or technician assignment was confirmed.'),F('engineer-repair.png','Report a repair form with authorized eligible-tool selection.'),
 O('8.3 Report a missing tool','Document a loss and preserve the existing accountability chain.','Engineer/Architect holder; eligible In Use tool without reservation/pending handover.', ['Select Missing. Choose Tool in Report a missing tool.','Enter Last seen and circumstances with factual details (at most 2,000 characters).','Select Submit missing report and note the MIS- reference.','Review the saved case and inform Admin when the equipment is found so Admin can record the inspected recovery.'],'The tool becomes Missing and a case/activity entry is saved; existing holder/location remain.','Only Admin can Confirm recovery. This report does not assign blame. Do not manually replace custody or hide the original case after finding equipment.'),F('engineer-missing.png','Report a missing tool form; no loss is submitted.'),
 O('8.4 Read notifications and follow overdue equipment','Follow authorized alerts to their supporting records.','Engineer/Architect with monitoring configured; relevant recorded notices.', ['Select the topbar bell to open Notifications.','Review Currently overdue requests, tool IDs and days past the needed-until date. Select a request reference to inspect it.','For a recorded notice, select Open and mark read to update your notice and open its authorized target.','Review the original request/transfer before taking the appropriate return or follow-up action.'],'Your own recorded notices and authorized overdue requests are visible.','Opening the bell alone does not mark all notices read. Overdue/weekly generation requires the trusted backend scheduler. A direct transfer without a linked received request/needed-until date is not automatically the same overdue loan. No SMS, push or email-reminder workflow was confirmed.'),
 O('8.5 Search/export authorized movement history','Keep a record of your permitted equipment transactions.','Engineer/Architect; Activity Logs access.', ['Select Activity Logs. Enter a reference, tool ID, person, action or summary text in Search activity.','Select a linked action/reference to open its saved request, transfer, return or report.','Select Export CSV when a local copy is required and open mcpa-movement-activity.csv.'],'An authorized movement-event history is displayed or exported.','The CSV contains authorized movement activity matching the current activity search. It is not an account/purchase/material audit. Preserve private work data when sharing.'),F('engineer-activity.png','Engineer Activity Logs and movement links.'),
 H('8.6 Preferences and offline demo'),P('Settings offers My account, display mode and Log Out as described in Chapter 2. Password reset begins after signing out. The login page’s Try offline demo offers Admin, Engineer or Architect sample identities and browser-only records. Demo has no live database access and hides accounts, Material Requests and Purchases; Projects is read-only and Your receiving QR requires an authenticated company account. Do not treat demo records as company transactions.'),source('1-admin/modules/sites/sites.js; js/movement-ui.js; js/movement-overview.js; js/monitoring.js; js/auth.js and js/permissions.js.'),
 H('Chapter 9 — Troubleshooting and Best Practices',1),H('9.1 Common issues'),T(['Symptom / message','What to do'],[...sharedIssues,['No eligible tools are available.','Check the tool’s current holder, status, quantity, approved reservation and pending/refused transfer. Request unheld stock; transfer/return only your eligible held tools.'],['Request tools for a project assigned to your account.','Ask Admin to assign your actual profile; choosing a destination in the dropdown does not grant project authority.'],['No assigned receiving project.','Ask Admin for an active receiving-project assignment. A separate project may be needed because the model has one accountable profile per project.'],['This receiving QR is expired or revoked.','Ask the receiver to generate a fresh QR, or use verified manual details. Generating a new QR invalidates older ones.'],['This is not a receiving QR.','Use Your receiving QR before sending. Use the handover code/QR after dispatch, and the equipment tag only for identification.'],['Camera scanning could not load / requires HTTPS or localhost','Use the configured secure application, allow permission, or use Enter Details Manually / handover-code entry. A missing scanner library cannot be fixed by submitting an unverified transaction.'],['Camera permission denied or scan not detected','Allow camera access in the browser, use the rear camera, show the original code clearly and retry. Close/Stop camera when finished. Optical scanning and actual device permissions were not verified here.'],['Inspect every selected tool / Test each received tool','Select every condition; add damage/missing notes; test/check every non-missing tool; choose a damaged-custody decision.'],['Only the named receiver can confirm receipt.','Ask the correctly named receiving account to sign in. Possession of a code does not grant receipt permission.'],['Tool custody or status changed after dispatch.','Refresh and coordinate the original transfer with Admin/sender. Do not create another handover to conceal a conflict.'],['Refused handover remains locked','The reservation is intentionally held. Eligible original sender may reopen/cancel; the linked-request requester may cancel. Admin monitors.'],['Expected tool disappears after return/transfer','Successful good return or accepted transfer changes custody. Check its saved history in Returns/Transfers/Activity Logs. Damaged/missing items can remain your responsibility.']]),
 H('9.2 Frequently Asked Questions'),P('Are Engineer and Architect permissions different? No. They share the same modules/actions and backend checks; individual ownership and assignment can produce different visible records.'),P('Can I transfer a tool held by another person? No. The current holder sends it. Tool Handler dispatch is separately limited to eligible available equipment with no holder.'),P('Does scanning a QR accept custody? No. Receiving QR fills a verified receiver/project; handover lookup opens the transaction. Receipt requires all saved inspections and confirmation.'),P('Can I accept part of a bulk quantity? No partial-quantity split/receipt field is implemented for equipment records. Resolve the physical discrepancy before recording a whole-record outcome.'),P('Can I edit/cancel a completed transfer or saved return? No current UI procedure supports undoing completed custody or deleting history. Contact Admin and preserve the original reference.'),P('Can I request materials or open reports? Engineer/Architect cannot access Material Requests, Purchases or Reports under the current role map. Ask Admin or Secretary for materials workflow; Activity Logs CSV remains available to you.'),P('Who clears damaged/lost-tool accountability? The damage/loss is recorded first; Admin completion/recovery clears or resolves custody as implemented. Good returns clear the holder immediately. An accepted damaged transfer assigns the receiver and opens repair follow-up.'),
 H('9.3 Field best practices'),L(['Check asset identity and whole-record quantity before selection. Keep the physical count consistent with the saved asset record.','Record dispatch before tools leave the source. Confirm exact receiver/project, especially where names are similar.','Use a fresh receiving QR and the original transfer reference. Do not send authentication passwords or receiving secrets in screenshots.','Physically inspect and test tools before confirming receipt; document damage/missing facts. Refuse eligible damaged handovers when appropriate and coordinate follow-up.','Keep original references for pending/refused/canceled transactions. Do not create duplicate handovers to work around a lock.','Submit returns using actual destinations and per-tool condition. Damaged/missing outcomes preserve accountability until resolution.','Check saved records after connection loss before starting a new operation. Preserve drafts and wait for refresh after a confirmed save.','Review overdue notices and authorized history, protect exports, and use Log Out on shared devices.']),
 H('Glossary',1),T(['Term','Meaning'],glossary),H('Evidence, validation and revision information',1),P('The companion system review includes the role-permission matrix, current module list, relevant source files, screenshot manifest and limitations. Screenshots prove actual local rendering under the stated fixture conditions. They do not prove real optical QR capture, deployed Auth/Storage/email/scheduler behavior or successful execution of every documented company write.'),T(['Version','Date','Revision'],[[version,date,'Initial Engineer/Architect manual, identical role-policy finding, genuine isolated UI captures, explicit custody/return/refusal and deployment limits.']]),P('Future revision: update this manual whenever labels, eligibility, ownership rules, role maps or backend migrations change. Capture new figures with safe dedicated staging records; preserve protected live transactions.')
]};
module.exports={admin,engineer};
